-- A version an admin has confirmed the publication date of is scheduled, and an indicator holds at
-- most one unpublished version, draft or scheduled. internal_api already updates indicator_version
-- and adds to audit_log at table level, so no grants change. Nothing is scheduled yet: no backfill.
ALTER TABLE "audit_log" DROP CONSTRAINT "audit_log_action_check";--> statement-breakpoint
ALTER TABLE "indicator_version" DROP CONSTRAINT "indicator_version_status_check";--> statement-breakpoint
DROP INDEX "idx_indicator_version_one_draft";--> statement-breakpoint
CREATE UNIQUE INDEX "idx_indicator_version_one_unpublished" ON "indicator_version" USING btree ("indicator_id") WHERE "indicator_version"."status" IN ('draft', 'scheduled');--> statement-breakpoint
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_action_check" CHECK ("audit_log"."action" IN ('topic.created', 'topic.updated', 'topic.deleted', 'indicator.draft_created', 'indicator.draft_updated', 'indicator.draft_created_from_published', 'indicator.data_table_confirmed', 'indicator.submitted', 'indicator.submission_withdrawn', 'indicator.reviewers_assigned', 'indicator.review_feedback_given', 'indicator.changes_requested', 'indicator.approved', 'indicator.resubmitted', 'indicator.revision_response_updated', 'indicator.publication_scheduled', 'indicator.publication_date_changed', 'indicator.review_note_added', 'indicator.review_note_updated', 'upload_batch.loaded', 'upload_batch.refused', 'upload_batch.deleted', 'data_migration.applied', 'subtopic.created', 'subtopic.updated', 'ci_method.created', 'ci_method.updated', 'classification.created', 'classification.updated', 'data_provider.created', 'data_provider.updated', 'data_provider_source.created', 'data_provider_source.updated', 'value_type.created', 'value_type.updated', 'unit.created', 'unit.updated', 'comparator_method.created', 'comparator_method.updated'));--> statement-breakpoint
ALTER TABLE "indicator_version" ADD CONSTRAINT "indicator_version_status_check" CHECK ("indicator_version"."status" IN ('draft', 'scheduled', 'published'));